CustomField.formula:
IF( NOT(ISBLANK(Unit__r.Unit_Sold_Date__c)),
IF( OR( Unit__r.Category__c = "MEGA MANSIONS", Unit__r.Category__c = "MANSIONS" ),
/* MANSIONS / MEGA MANSIONS logic */ CASE(ProjectName__c, "Nawayef West", IF(Unit__r.Unit_Sold_Date__c <= DATE(2024, 11, 30), "2%", "3%"), "Nawayef East", IF(Unit__r.Unit_Sold_Date__c <= DATE(2024, 11, 30), "2%", "3%"), "AED 0 (0%)" ),
/* Non-mansion logic */ CASE(ProjectName__c, "Al Naseem", IF(Unit__r.Unit_Sold_Date__c <= DATE(2024, 11, 30), "2%", "4%"), "Muheira", "4%", "Maysan", "3%", "Nawayef West", IF(Unit__r.Unit_Sold_Date__c <= DATE(2024, 11, 30), "2%", "4%"), "Nawayef East", IF(Unit__r.Unit_Sold_Date__c <= DATE(2024, 11, 30), "2%", "4%"), "Nawayef Park View", "3%", "Nawayef Village Townhouses", "4%", "" ) ),
/* If Unit_Sold_Date__c is blank, return blank */ "" )
